// The row brings the scene; the preset's subject brings the character. {{subject.hero}} is expanded by ImageStep to
// the words saved on the preset — it is built here, in code, because n8n reads {{ }} in a field as its own expression.
return $input.all().map((item) => ({
  json: {
    row_number: item.json.row_number,
    prompt: `${item.json.headline}. ${item.json.subline}. Social carousel card, {{subject.hero}} as the hero, clean background with room for text, 4:5 portrait.`
  }
}));

// One row per sheet row: the four published URLs as url1..url4 plus the job id.
return $input.all().map((item) => {
  const urls = (item.json.outputs || []).map((o) => o.publicUrl);
  return {
    json: {
      row_number: $('Google Sheets Trigger').item.json.row_number,
      jobId: item.json.jobId,
      status: item.json.status,
      url1: urls[0] || '',
      url2: urls[1] || '',
      url3: urls[2] || '',
      url4: urls[3] || ''
    }
  };
});
